// service-worker.js
// 利用 Web Locks 保持 Service Worker 存活
async function keepAlive() {
  await navigator.locks.request('sw-keep-alive', () => {
    // 返回一个永远不 resolve 的 Promise，阻止锁释放
    return new Promise(() => {})
  })
}

self.addEventListener('activate', (event) => {
  event.waitUntil(keepAlive())
})

